``` {.python .cell-code code-line-numbers="|3-10|1-2,11|13"}
def some_theme(gt: GT) -> GT:
    return (
        gt
        .opt_row_striping()
        .opt_table_font(font="Courier")
        .tab_options(
            heading_align="left",
            column_labels_text_transform="lowercase",
            row_striping_background_color="#b5dbb6",
        )
    )

gt.pipe(some_theme)
```
