def fmt_threshold(gt, columns, threshold: float):

    def _truncate(val: float):
        if val < threshold:
            return f"<{threshold}"
        else:
            return str(val)

    return gt.fmt(_truncate, columns)

gt.pipe(fmt_threshold, "Wind", 10.0)
